"""Static interface for the BCI embedding atlas."""

HTML = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BCI canopy atlas</title><style>
:root{font:15px/1.5 'Avenir Next',Avenir,system-ui,sans-serif;color:#183448;background:#edf3f7}*{box-sizing:border-box}body{margin:0}header{padding:22px 28px;background:#173a50;color:white;display:flex;align-items:baseline;gap:24px;flex-wrap:wrap}h1{font-size:26px;margin:0;letter-spacing:-.7px}header p{margin:0;color:#c6dbe7}main{padding:20px;display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px}.workspace{min-width:0}.toolbar{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px}input,select,button{font:inherit;padding:9px 12px;border:1px solid #a5bbc9;border-radius:5px;background:white;color:#173a50}button{cursor:pointer}button:hover{background:#e3edf4}:focus-visible{outline:3px solid #087eab;outline-offset:3px}.views{display:grid;grid-template-columns:1.4fr 1fr;gap:12px}.view{background:white;border:1px solid #c6d6df;border-radius:8px;overflow:hidden;position:relative}h2{font-size:17px;margin:0;padding:12px 16px}.view p{font-size:12px;padding:0 16px;margin:0 0 10px;color:#4c6778}canvas{display:block;width:100%;height:520px;touch-action:none;background:#dbe8ed;cursor:crosshair}.plot{background:#f7fafc}aside{background:#fff;border-radius:8px;border:1px solid #c6d6df;padding:18px;min-width:0}aside h2{padding:0;margin-bottom:12px}#photo{width:100%;height:155px;object-fit:cover;background:#e4edf2;border-radius:4px}#key{overflow-wrap:anywhere;font-size:13px}small,.muted{color:#4c6778}ol{padding-left:25px}li{margin:6px 0}li button{font-size:12px;text-align:left;width:100%;padding:7px}#results{max-height:235px;overflow:auto;border-top:1px solid #dbe4eb;margin-top:12px}#results button{display:block;width:100%;border:0;border-bottom:1px solid #e0e8ed;text-align:left;font-size:12px;border-radius:0}#results button[aria-pressed=true]{background:#cfe6f2}details{margin-top:18px;background:white;padding:14px;border-radius:6px}summary{cursor:pointer}#provenance{overflow-wrap:anywhere;font-size:12px}#status{font-size:13px;color:#476477}a{color:#076d96}.map-controls{position:absolute;right:10px;top:90px;display:flex;gap:4px}.attribution{position:absolute;bottom:0;right:0;background:#ffffffdf;font-size:10px;padding:2px 5px}@media(max-width:1000px){main{grid-template-columns:1fr}aside{display:grid;grid-template-columns:1fr 1fr;gap:12px}aside h2{grid-column:1/-1}#results{grid-column:1/-1}.views{grid-template-columns:1fr 1fr}canvas{height:400px}}@media(max-width:620px){header{padding:18px;gap:5px}main{padding:10px}.views{grid-template-columns:1fr}canvas{height:320px}aside{display:block}input{width:100%}.toolbar{align-items:stretch}h1{font-size:24px}}
</style><header><h1>BCI canopy atlas</h1><p>Explore how forest photos relate, in the field and in the model.</p></header><nav aria-label="Dashboard views" style="padding:12px 28px;display:flex;gap:20px;flex-wrap:wrap"><a href="embedding-atlas.html">Pl@ntNet frame atlas</a><a href="crownfirst-atlas.html">Crownfirst canopy atlas</a><a href="model_health_dashboard.html">Model health</a><a href="label_queue_dashboard.html">Labelling queue</a></nav><main><section class="workspace"><div class="toolbar"><input id="search" type="search" aria-label="Find a frame or mission" placeholder="Find a frame or mission"><select id="group" aria-label="Frame population"><option>All frames</option><option>Labelled</option><option>To label</option><option>Crownfirst pool</option></select><button id="reset">Reset view</button><span id="status" role="status" aria-live="polite"></span></div><div class="views"><section class="view"><h2>Camera positions</h2><p>Drag to pan. Scroll or use + / − to zoom. Points mark aircraft positions, not individual trees.</p><canvas id="map" aria-label="Geographic camera positions. Select frames using the list." role="img"></canvas><div class="map-controls"><button id="zoomIn" aria-label="Zoom in">+</button><button id="zoomOut" aria-label="Zoom out">−</button></div><span class="attribution">© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors</span></section><section class="view"><h2>Visual relationships</h2><p>PCA overview. Similar colors share representation features, not necessarily a species.</p><canvas id="plot" class="plot" role="img" aria-label="Two dimensional PCA representation. Select frames using the list."></canvas></section></div><details><summary>How to read this atlas</summary><p>Select a frame in either view or the list. Its closest visual matches are ranked using the full embedding, not distance in the two dimensional plot. Nearby camera positions can show different crowns. Unlabelled matches are suggestions for inspection, not identifications.</p><p>The same PCA components color both views. Projection and color compress information and do not establish biological similarity, habitat classes, species, or crown boundaries. The source encoder and artifact hashes below identify this frozen representation. This is not an AlphaEarth habitat product.</p><div id="provenance"></div></details></section><aside><h2>Inspect a frame</h2><div><img id="photo" alt="Selected drone frame" loading="lazy" referrerpolicy="no-referrer"><p id="key"></p><p id="detail" class="muted"></p><a id="original" target="_blank" rel="noopener noreferrer">Open full image</a></div><div><h3>Closest visual matches</h3><small>Full-dimensional cosine similarity. Higher means more alike to this encoder.</small><ol id="neighbors"></ol></div><div id="results" aria-label="Matching frames"></div></aside></main><script id="atlas-data" type="application/json">__ATLAS_DATA__</script><script>
'use strict';const data=JSON.parse(document.getElementById('atlas-data').textContent),P=data.points,$=id=>document.getElementById(id);let selected=0,visible=P.map((_,i)=>i),view,tiles=new Map(),mapHits=[],plotHits=[];const map=$('map'),plot=$('plot');
function merc(p){return [(p.lon+180)/360,(1-Math.asinh(Math.tan(p.lat*Math.PI/180))/Math.PI)/2]};const geo=P.map(merc);function fit(){let xs=visible.map(i=>geo[i][0]),ys=visible.map(i=>geo[i][1]);if(!xs.length)return;view={x:(Math.min(...xs)+Math.max(...xs))/2,y:(Math.min(...ys)+Math.max(...ys))/2,scale:1};view.scale=Math.min(map.clientWidth/Math.max(Math.max(...xs)-Math.min(...xs),.00001),map.clientHeight/Math.max(Math.max(...ys)-Math.min(...ys),.00001))*.8;draw()}
function setup(c){let d=devicePixelRatio||1;c.width=c.clientWidth*d;c.height=c.clientHeight*d;let ctx=c.getContext('2d');ctx.scale(d,d);return ctx}
function point(ctx,x,y,i,near){ctx.beginPath();ctx.arc(x,y,i===selected?7:near.has(i)?5:3,0,Math.PI*2);ctx.fillStyle=`rgb(${P[i].rgb.join(',')})`;ctx.fill();if(i===selected||near.has(i)){ctx.strokeStyle=i===selected?'#06283b':'#fff';ctx.lineWidth=2;ctx.stroke()}}
function draw(){if(!view)return;const ctx=setup(map),pc=setup(plot),w=map.clientWidth,h=map.clientHeight,pw=plot.clientWidth,ph=plot.clientHeight;ctx.fillStyle='#dbe8ed';ctx.fillRect(0,0,w,h);let z=Math.max(1,Math.min(19,Math.floor(Math.log2(view.scale/256)))),n=2**z,tileSize=view.scale/n,left=view.x-w/2/view.scale,top=view.y-h/2/view.scale;for(let tx=Math.floor(left*n);tx<=Math.ceil((left+w/view.scale)*n);tx++)for(let ty=Math.floor(top*n);ty<=Math.ceil((top+h/view.scale)*n);ty++){if(ty<0||ty>=n)continue;let key=`${z}/${((tx%n)+n)%n}/${ty}`,im=tiles.get(key);if(!im){im=new Image();im.onload=()=>requestAnimationFrame(draw);im.src='https://tile.openstreetmap.org/'+key+'.png';tiles.set(key,im)}if(im.complete&&im.naturalWidth)ctx.drawImage(im,(tx/n-left)*view.scale,(ty/n-top)*view.scale,tileSize+1,tileSize+1)}let xs=P.map(p=>p.xy[0]),ys=P.map(p=>p.xy[1]),minx=Math.min(...xs),miny=Math.min(...ys),rx=Math.max(...xs)-minx||1,ry=Math.max(...ys)-miny||1;pc.fillStyle='#f7fafc';pc.fillRect(0,0,pw,ph);let near=new Set(P[selected].neighbours.map(n=>n[0]));mapHits=[];plotHits=[];let order=visible.filter(i=>i!==selected);if(visible.includes(selected))order.push(selected);for(let i of order){let x=(geo[i][0]-view.x)*view.scale+w/2,y=(geo[i][1]-view.y)*view.scale+h/2;point(ctx,x,y,i,near);mapHits.push([x,y,i]);let px=25+(P[i].xy[0]-minx)/rx*(pw-50),py=ph-25-(P[i].xy[1]-miny)/ry*(ph-50);point(pc,px,py,i,near);plotHits.push([px,py,i])}}
function select(i){selected=i;let p=P[i];$('key').textContent=p.key;$('detail').textContent=`${p.group}. ${p.lat.toFixed(5)}, ${p.lon.toFixed(5)}. ${p.crop ? p.crop+'px center crop.' : 'Crop geometry unavailable in this source.'}`;if(/^https?:\/\//.test(p.image)){$('photo').src=p.image;$('original').href=p.image}else{$('photo').removeAttribute('src');$('original').removeAttribute('href')}$('neighbors').replaceChildren(...p.neighbours.slice(0,6).map(([j,s])=>{let li=document.createElement('li'),b=document.createElement('button');b.textContent=`${P[j].key.replace('comb_DJI_','')} · ${s.toFixed(3)}`;b.onclick=()=>select(j);li.append(b);return li}));list();draw()}
function list(){let rows=visible.slice(0,150);if(visible.includes(selected)&&!rows.includes(selected))rows.unshift(selected);$('results').replaceChildren(...rows.map(i=>{let b=document.createElement('button');b.textContent=P[i].key.replace('comb_DJI_','')+' · '+P[i].group;b.setAttribute('aria-pressed',i===selected);b.onclick=()=>select(i);return b}));$('status').textContent=`${visible.length.toLocaleString()} of ${P.length.toLocaleString()} frames. List shows up to 150 matches.`}
function filter(){let q=$('search').value.trim().toLowerCase(),g=$('group').value;visible=P.map((_,i)=>i).filter(i=>(g==='All frames'||P[i].group===g)&&`${P[i].key} ${P[i].mission}`.toLowerCase().includes(q));list();draw()}
$('search').oninput=filter;$('group').onchange=filter;$('reset').onclick=()=>{$('search').value='';$('group').value='All frames';filter();fit()};$('zoomIn').onclick=()=>{view.scale*=1.6;draw()};$('zoomOut').onclick=()=>{view.scale/=1.6;draw()};map.onwheel=e=>{e.preventDefault();view.scale*=e.deltaY<0?1.25:.8;draw()};map.addEventListener('wheel',()=>{},{passive:false});let drag=null;map.onpointerdown=e=>{drag={x:e.offsetX,y:e.offsetY,ox:view.x,oy:view.y,moved:false};map.setPointerCapture(e.pointerId)};map.onpointermove=e=>{if(!drag)return;let dx=e.offsetX-drag.x,dy=e.offsetY-drag.y;if(Math.abs(dx)+Math.abs(dy)>4)drag.moved=true;view.x=drag.ox-dx/view.scale;view.y=drag.oy-dy/view.scale;draw()};function hit(e,hits){let best=hits.map(([x,y,i])=>[Math.hypot(x-e.offsetX,y-e.offsetY),i]).sort((a,b)=>a[0]-b[0])[0];if(best&&best[0]<15)select(best[1])}map.onpointerup=e=>{if(drag&&!drag.moved)hit(e,mapHits);drag=null};map.onpointercancel=()=>drag=null;plot.onclick=e=>hit(e,plotHits);window.addEventListener('resize',draw);const pr=data.provenance;$('provenance').textContent=`${pr.encoder}, ${pr.versions.join(', ')}, ${pr.dimensions} dimensions. ${pr.projection}. Two plotted components retain ${(100*(pr.pca_explained_variance||[]).slice(0,2).reduce((a,b)=>a+b,0)).toFixed(1)}% of variance. ${pr.input_count} input frames; ${Object.values(pr.excluded).reduce((a,b)=>a+b,0)} excluded. Source SHA-256: ${pr.sources.map(s=>s.file+': '+s.sha256).join('; ')}`;fit();select(0);
</script></html>
'''
